#!/usr/bin/env python3
import base64
import datetime
import fcntl
import hashlib
import os
import re
import shutil
import tempfile
from pathlib import Path

ROOT = Path('/var/www/azmednsk-preview')
BACKUPS = Path('/var/backups/azmednsk')
PEOPLE = (
    ('Черевко', 'Анна Сергеевна', 'cherevko', 'Старшая медицинская сестра', '71b601f55a4eeb447bee83374901372ce82449973db8720759377400e3e15957', ''),
    ('Алатарцева', 'Полина Владиславовна', 'alatartseva', 'Ассистент стоматолога', 'cef8604304788a01a68dc93676e384ab0152a59c9c4fff8ef442577950998dcc', ''),
    ('Борисовская', 'Алина Игоревна', 'borisovskaya', 'Ассистент стоматолога', 'b53ca3faf8a58e185b3282c25287da354ff3b217480bd16bca899bda1fce0c15', ''),
    ('Абдурахимов', 'Халим Хамзаевич', 'abdurakhimov', 'Ассистент стоматолога', 'e19e0af3302dfd36112182ceca39b554c1eda07a40cf4d79446029945b07b92d', ''),
)

def demand(condition, message):
    if not condition:
        raise ValueError(message)

def build_cards():
    cards = []
    photos = {}
    for surname, given, slug, role, digest, encoded in PEOPLE:
        name = surname + ' ' + given
        url = '/assets/team2-v1/dental-' + slug + '-' + digest[:8] + '.webp'
        data = base64.b64decode(encoded, validate=True)
        demand(hashlib.sha256(data).hexdigest() == digest, 'Ошибка контрольной суммы: ' + name)
        photos[url] = data
        cards.append(
            f'<article class="person" tabindex="-1" id="person-{slug}" data-search="{name.lower()} {role.lower()}">'
            f'<img loading="lazy" decoding="async" src="{url}" alt="{name}" width="640" height="960">'
            f'<div class="copy"><h3>{surname}<span>{given}</span></h3><p>{role}</p><small></small>'
            '<a href="#help">Уточнить у администратора →</a></div></article>'
        )
    return ''.join(cards), photos

def update_html(original, cards):
    sections = list(re.finditer(r'<section\b[^>]*\bid="dentistry"[^>]*>.*?</section>', original, re.S))
    demand(len(sections) == 1, 'Проверьте раздел стоматологии')
    section = sections[0]
    html = section.group()
    group_photo = 'src="/assets/team2-v1/team2-assistants-1.webp"'
    figures = [figure for figure in re.finditer(r'<figure\b[^>]*>.*?</figure>', html, re.S)
               if group_photo in figure.group()]
    demand(len(figures) == 1, 'Общее фото с перчатками не найдено однозначно')
    gallery = figures[0]
    prefix = html[:gallery.start()]
    demand(prefix.endswith('</article></div>') and 'class="t2-duo t2-follow"' in prefix
           and 'class="grid t2-people"' in prefix.split('class="t2-duo t2-follow"')[-1],
           'Изменилась структура карточек рядом с общим фото')
    insertion_offset = len(prefix) - len('</div>')
    installed = prefix[:insertion_offset].endswith(cards)
    baseline = original.replace(cards, '', 1) if installed else original
    for surname, given, slug, _, _, _ in PEOPLE:
        demand(f'id="person-{slug}"' not in baseline and f'{surname} {given}'.casefold() not in baseline.casefold(),
               'Конфликт существующей карточки: ' + surname)

    photo = gallery.group()
    caption = '<figcaption><span>Ассистенты</span></figcaption>'
    if '<figcaption' in photo:
        demand(photo.count(caption) == 1 and photo.count('<figcaption') == 1,
               'Подпись под общим фото изменилась')
        photo = photo.replace(caption, '', 1)
    if not installed:
        prefix = prefix[:insertion_offset] + cards + prefix[insertion_offset:]
    result = prefix + photo + html[gallery.end():]
    return original[:section.start()] + result + original[section.end():]


def stage(path, data):
    with tempfile.NamedTemporaryFile(dir=path.parent, prefix='.dental-', delete=False) as temp:
        temp.write(data)
        temp.flush()
        os.fsync(temp.fileno())
    return Path(temp.name)

def install(root, backups):
    page = root / 'team/index.html'
    folder = root / 'assets/team2-v1'
    demand(page.resolve() == page and folder.resolve() == folder and folder.is_dir(), 'Проверьте пути сайта')
    folder_fd = os.open(page.parent, os.O_RDONLY)
    try:
        fcntl.flock(folder_fd, fcntl.LOCK_EX)
        before = page.read_bytes()
        cards, photos = build_cards()
        after = update_html(before.decode('utf-8'), cards).encode('utf-8')
        missing = {}
        for url, data in photos.items():
            asset = root / url.lstrip('/')
            demand(not asset.is_symlink(), 'Символическая ссылка: ' + str(asset))
            if asset.exists():
                demand(asset.read_bytes() == data, 'Конфликт файла: ' + str(asset))
            else:
                missing[asset] = data
        if before == after and not missing:
            print('DENTAL_STAFF=ALREADY_APPLIED; CAPTION=REMOVED')
            return
        stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
        backup = backups / ('team-dental-staff-' + stamp)
        backup.mkdir(mode=0o700, parents=True)
        shutil.copy2(page, backup / 'index.html')
        demand((backup / 'index.html').read_bytes() == before, 'Страница изменилась во время копирования')
        for asset, data in missing.items():
            temp = stage(asset, data)
            try:
                temp.chmod(0o644)
                os.link(temp, asset)
            finally:
                temp.unlink()
        if before != after:
            temp = stage(page, after)
            try:
                st = page.stat()
                if os.geteuid() == 0:
                    os.chown(temp, st.st_uid, st.st_gid)
                temp.chmod(st.st_mode & 0o7777)
                demand(page.read_bytes() == before, 'Страница изменилась, повторите запуск')
                os.replace(temp, page)
            finally:
                if temp.exists():
                    temp.unlink()
        demand(page.read_bytes() == after, 'Ошибка проверки страницы')
        for url, data in photos.items():
            demand((root / url.lstrip('/')).read_bytes() == data, 'Ошибка проверки ' + url)
        print('DENTAL_STAFF=PASS; CARDS=4; PHOTOS=VERIFIED; CAPTION=REMOVED')
        print('BACKUP=' + str(backup))
    finally:
        os.close(folder_fd)

if __name__ == '__main__':
    install(ROOT, BACKUPS)
    print('URL=https://azmednsk.ru/team/#dentistry')
